import java.util.Scanner

fun special(u: Int, k: Int, a: IntArray): Int {
    return when {
        a[u] == 1 -> k - u
        a[k] == 1000 -> k - u
        else -> k - u - 1
    }
}

fun main() {
    val sc = Scanner(System.`in`)
    val n = sc.nextInt()
    val a = IntArray(n)
    for (i in 0 until n) {
        a[i] = sc.nextInt()
    }
    a.sort()
    var max = 0
    var u = 0
    var k = 0
    var g = true
    for (i in 0 until n - 1) {
        if (a[i + 1] - a[i] == 1 && g) {
            u = i
            g = false
        }
        if (a[i + 1] - a[i] != 1 && !g) {
            k = i
            g = true
            val l = special(u, k, a)
            if (l > max) max = l
        }
    }
    if (!g) {
        k = n - 1
        val l = special(u, k, a)
        if (l > max) max = l
    }
    println(max)
}

